-- Canonical IAM reference data consolidated from the verified migration history.
-- This seed intentionally contains only system roles, permissions and technical system accounts.


    account_id,
    user_profile_id,
    username,
    email,
    role_id,
    status,
    failed_login_count,
    password_changed_at,
    created_at,
    updated_at
)
SELECT
    '20000000-0000-0000-0000-00000000a001',
    NULL,
    'SYSTEM',
    'system@vehicle-management.local',
    role.role_id,
    'ACTIVE',
    0,
    now(),
    now(),
    now()
FROM iam.roles role
WHERE role.code = 'SYSTEM_ADMIN';

-- Technical account mirrored by the Keycloak realm import. This is the only
-- account retained from legacy V13; personal EMPLOYEE/PARKING_MANAGER demo
-- accounts are intentionally excluded from production reference data.
    user_profile_id,
    full_name,
    status,
    created_at,
    updated_at
)
VALUES (
    '10000000-0000-0000-0000-00000000a002',
    'Vehicle Management System Admin',
    'ACTIVE',
    now(),
    now()
);

    account_id,
    user_profile_id,
    username,
    email,
    keycloak_user_id,
    role_id,
    status,
    failed_login_count,
    password_changed_at,
    created_at,
    updated_at
)
SELECT
    '20000000-0000-0000-0000-00000000a002',
    '10000000-0000-0000-0000-00000000a002',
    'vehiclemanagement.noreply',
    'vehiclemanagement.noreply@gmail.com',
    '54fd8e18-9f9d-4d93-8f63-f4f0374da001',
    role.role_id,
    'ACTIVE',
    0,
    now(),
    now(),
    now()
FROM iam.roles role
WHERE role.code = 'SYSTEM_ADMIN';

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM iam.accounts account
        JOIN iam.roles role ON role.role_id = account.role_id
        JOIN people.user_profiles profile ON profile.user_profile_id = account.user_profile_id
        WHERE account.account_id = '20000000-0000-0000-0000-00000000a002'
          AND account.username = 'vehiclemanagement.noreply'
          AND account.email = 'vehiclemanagement.noreply@gmail.com'
          AND account.keycloak_user_id = '54fd8e18-9f9d-4d93-8f63-f4f0374da001'
          AND account.status = 'ACTIVE'
          AND role.code = 'SYSTEM_ADMIN'
          AND profile.user_profile_id = '10000000-0000-0000-0000-00000000a002'
          AND profile.status = 'ACTIVE'
    ) THEN
        RAISE EXCEPTION 'Missing or invalid vehiclemanagement.noreply SYSTEM_ADMIN account.';
    END IF;
END $$;

DO $$
DECLARE
    missing_permission_codes TEXT;
BEGIN
    WITH required_permissions(permission_code) AS (
        VALUES
        ('ACCOUNT_CREATE_ALL'),
        ('ACCOUNT_READ_ALL'),
        ('ACCOUNT_UPDATE_ALL'),
        ('BROADCAST_NOTIFICATION_CANCEL_ALL'),
        ('BROADCAST_NOTIFICATION_CREATE_ALL'),
        ('BROADCAST_NOTIFICATION_DELETE_ALL'),
        ('BROADCAST_NOTIFICATION_PUBLISH_ALL'),
        ('BROADCAST_NOTIFICATION_READ_ALL'),
        ('BROADCAST_NOTIFICATION_UPDATE_ALL'),
        ('CARD_CREATE_ALL'),
        ('CARD_DELETE_ALL'),
        ('CARD_READ_ALL'),
        ('CARD_TYPE_CREATE_ALL'),
        ('CARD_TYPE_DELETE_ALL'),
        ('CARD_TYPE_READ_ALL'),
        ('CARD_TYPE_UPDATE_ALL'),
        ('CARD_UPDATE_ALL'),
        ('CHAT_ATTACHMENT_CREATE_OWN'),
        ('CHAT_ATTACHMENT_READ_OWN'),
        ('CHAT_CONVERSATION_CREATE_ALL'),
        ('CHAT_CONVERSATION_CREATE_OWN'),
        ('CHAT_CONVERSATION_READ_ALL'),
        ('CHAT_CONVERSATION_READ_OWN'),
        ('CHAT_CONVERSATION_UPDATE_ALL'),
        ('CHAT_MESSAGE_MODERATE_ALL'),
        ('CHAT_MESSAGE_SEND_OWN'),
        ('CUSTOMER_READ_ALL'),
        ('CUSTOMER_UPDATE_ALL'),
        ('CUSTOMER_VEHICLE_CREATE_ALL'),
        ('CUSTOMER_VEHICLE_CREATE_OWN'),
        ('CUSTOMER_VEHICLE_DELETE_ALL'),
        ('CUSTOMER_VEHICLE_DELETE_OWN'),
        ('CUSTOMER_VEHICLE_READ_ALL'),
        ('CUSTOMER_VEHICLE_READ_OWN'),
        ('CUSTOMER_VEHICLE_UPDATE_ALL'),
        ('CUSTOMER_VEHICLE_UPDATE_OWN'),
        ('DASHBOARD_READ_ALL'),
        ('DEVICE_CREATE_ALL'),
        ('DEVICE_DELETE_ALL'),
        ('DEVICE_READ_ALL'),
        ('DEVICE_STATUS_UPDATE_ALL'),
        ('DEVICE_UPDATE_ALL'),
        ('EMPLOYEE_DELETE_ALL'),
        ('EMPLOYEE_READ_ALL'),
        ('EMPLOYEE_UPDATE_ALL'),
        ('INVOICE_CANCEL_ALL'),
        ('INVOICE_CREATE_ALL'),
        ('INVOICE_READ_ALL'),
        ('INVOICE_READ_OWN'),
        ('LOST_CARD_REPORT_CREATE_ALL'),
        ('LOST_CARD_REPORT_READ_ALL'),
        ('LOST_CARD_REPORT_UPDATE_ALL'),
        ('PARKING_SESSION_CHECK_IN_ALL'),
        ('PARKING_SESSION_CHECK_OUT_ALL'),
        ('PAYMENT_CREATE_ALL'),
        ('PAYMENT_CREATE_OWN'),
        ('PAYMENT_READ_ALL'),
        ('PERMISSION_READ_ALL'),
        ('ROLE_ASSIGN_PERMISSION_ALL'),
        ('ROLE_CREATE_ALL'),
        ('ROLE_DELETE_ALL'),
        ('ROLE_READ_ALL'),
        ('ROLE_REVOKE_PERMISSION_ALL'),
        ('ROLE_UPDATE_ALL'),
        ('SHIFT_ASSIGNMENT_CREATE_ALL'),
        ('SHIFT_ASSIGNMENT_DELETE_ALL'),
        ('SHIFT_ASSIGNMENT_READ_ALL'),
        ('SHIFT_ASSIGNMENT_READ_OWN'),
        ('SHIFT_ASSIGNMENT_UPDATE_ALL'),
        ('SHIFT_CREATE_ALL'),
        ('SHIFT_DELETE_ALL'),
        ('SHIFT_OPEN_OWN'),
        ('SHIFT_READ_ALL'),
        ('SHIFT_UPDATE_ALL'),
        ('SUBSCRIPTION_APPROVE_ALL'),
        ('SUBSCRIPTION_ASSIGN_CARD_ALL'),
        ('SUBSCRIPTION_CANCEL_ALL'),
        ('SUBSCRIPTION_CANCEL_OWN'),
        ('SUBSCRIPTION_CREATE_ALL'),
        ('SUBSCRIPTION_CREATE_OWN'),
        ('SUBSCRIPTION_EXPIRE_ALL'),
        ('SUBSCRIPTION_READ_ALL'),
        ('SUBSCRIPTION_READ_OWN'),
        ('SUBSCRIPTION_REJECT_ALL'),
        ('SUBSCRIPTION_UPDATE_ALL'),
        ('SUBSCRIPTION_UPDATE_OWN'),
        ('SUPPORT_TICKET_CLOSE_ALL'),
        ('SUPPORT_TICKET_CLOSE_OWN'),
        ('SUPPORT_TICKET_CREATE_OWN'),
        ('SUPPORT_TICKET_PROCESS_ALL'),
        ('SUPPORT_TICKET_PROCESS_ASSIGNED'),
        ('SUPPORT_TICKET_READ_ALL'),
        ('SUPPORT_TICKET_READ_ASSIGNED'),
        ('SUPPORT_TICKET_READ_OWN'),
        ('SUPPORT_TICKET_REOPEN_ALL'),
        ('SUPPORT_TICKET_REOPEN_OWN'),
        ('SUPPORT_TICKET_UPDATE_ALL'),
        ('SUPPORT_TICKET_UPDATE_OWN'),
        ('TICKET_TYPE_CREATE_ALL'),
        ('TICKET_TYPE_DELETE_ALL'),
        ('TICKET_TYPE_READ_ALL'),
        ('TICKET_TYPE_UPDATE_ALL'),
        ('USER_PROFILE_CREATE_ALL'),
        ('USER_PROFILE_READ_ALL'),
        ('USER_PROFILE_UPDATE_ALL'),
        ('VEHICLE_TYPE_CREATE_ALL'),
        ('VEHICLE_TYPE_DELETE_ALL'),
        ('VEHICLE_TYPE_READ_ALL'),
        ('VEHICLE_TYPE_UPDATE_ALL')
    )
    SELECT string_agg(required.permission_code, ', ' ORDER BY required.permission_code)
    INTO missing_permission_codes
    FROM required_permissions required
    LEFT JOIN iam.permissions permission
        ON permission.permission_code = required.permission_code
    WHERE permission.permission_id IS NULL;

    IF missing_permission_codes IS NOT NULL THEN
        RAISE EXCEPTION 'Missing permissions referenced by backend code: %', missing_permission_codes;
    END IF;
END $$;
